WITH valid_order_items AS (SELECT *, ROUND(unit_price, 2) AS unit_price_rounded FROM order_items WHERE quantity >= 4), OrderItemsStats AS (SELECT order_id, MIN(unit_price_rounded) AS min_unit_price_rounded FROM valid_order_items GROUP BY order_id) SELECT order_id, min_unit_price_rounded FROM OrderItemsStats WHERE min_unit_price_rounded > 46 ORDER BY order_id DESC, min_unit_price_rounded DESC
